// Typeset the transcript like the terminals this genre was born on.
const adv = nb.get('adventure');
if (!adv) return 'Run the Clojure cell first.';

console.log('turns:', adv.turns.length, '| escaped:', adv.escaped, '| gold:', adv.gold);

const rows = adv.turns.map(t =>
  '<div style="margin:6px 0">' +
  '<div style="color:#4ade80">&gt; ' + t.cmd + '</div>' +
  '<div style="color:#d4d4d8;padding-left:16px">' + t.text + '</div>' +
  '</div>').join('');

return '<div style="background:#09090b;border-radius:10px;padding:18px 20px;' +
  'font-family:ui-monospace,monospace;font-size:14px;max-width:640px">' +
  rows +
  '<div style="color:#facc15;margin-top:10px">*** You have escaped' +
  (adv.gold ? ', rich' : '') + '. Play again? ***</div></div>';
